// Generates the placeholder pixel art of Bekem in public/bekem/.
// Run with `npm run art`. Final artwork replaces the generated files; keep the
// file names and the frame layout of the sprite sheet run.svg (two square frames side by side).
import { mkdirSync, writeFileSync } from 'node:fs'
import path from 'node:path'

const ROOT = path.resolve(import.meta.dirname, '..', 'public')

const C = {
  ink: '#2b1d16',
  fur: '#b9814a',
  furDark: '#8f5f36',
  belly: '#f3dcae',
  white: '#ffffff',
  cheek: '#ef8f7a',
  coral: '#ef5d4a',
  sun: '#ffcf40',
  sunDeep: '#ffb52e',
  sky: '#bfe6f5',
  skyWarm: '#ffe2a8',
  skyGrey: '#b9c7d1',
  cloud: '#f4f7f9',
  grass: '#5fb04a',
  grassDark: '#3e8a35',
  grassLight: '#8fd46a',
  soil: '#8a5a3c',
  soilDark: '#6b4329',
  hot: '#d9864a',
  hotDark: '#a85a2a',
  hotLight: '#f0a868',
  water: '#4f86a8',
  waterDark: '#3a6a8c',
  waterLight: '#7fb3d1',
  stone: '#8b7d6b',
  stoneDark: '#6f6254',
  stoneLight: '#a89a86',
  rock: '#4a3b52',
  rockDark: '#35293d',
  rockLight: '#6a5874',
}

/** A pixel canvas. Colours are hex strings; null is transparent. */
class Canvas {
  constructor(width, height, fill = null) {
    this.width = width
    this.height = height
    this.pixels = Array.from({ length: height }, () => Array(width).fill(fill))
  }

  px(x, y, color) {
    if (x >= 0 && x < this.width && y >= 0 && y < this.height) this.pixels[y][x] = color
    return this
  }

  rect(x, y, w, h, color) {
    for (let j = y; j < y + h; j++) for (let i = x; i < x + w; i++) this.px(i, j, color)
    return this
  }

  /** Draws another canvas on top, skipping its transparent pixels. */
  draw(other, dx = 0, dy = 0) {
    other.pixels.forEach((row, y) => row.forEach((color, x) => color && this.px(x + dx, y + dy, color)))
    return this
  }

  toSvg() {
    const rects = []
    this.pixels.forEach((row, y) => {
      for (let x = 0; x < row.length; ) {
        const color = row[x]
        let end = x + 1
        while (end < row.length && row[end] === color) end++
        if (color) rects.push(`<rect x="${x}" y="${y}" width="${end - x}" height="1" fill="${color}"/>`)
        x = end
      }
    })
    return (
      `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${this.width} ${this.height}" shape-rendering="crispEdges">\n` +
      `  <!-- Placeholder pixel art, generated by scripts/placeholder-art.mjs. Replace with final artwork. -->\n  ` +
      rects.join('\n  ') +
      '\n</svg>\n'
    )
  }
}

function fromRows(rows, palette) {
  const width = rows[0].length
  const canvas = new Canvas(width, rows.length)
  rows.forEach((row, y) => {
    if (row.length !== width) throw new Error(`Row ${y} is ${row.length} wide, expected ${width}: "${row}"`)
    ;[...row].forEach((char, x) => {
      if (char === '.') return
      if (!(char in palette)) throw new Error(`Unknown pixel "${char}" in row ${y}`)
      canvas.px(x, y, palette[char])
    })
  })
  return canvas
}

function save(file, canvas) {
  const target = path.join(ROOT, file)
  mkdirSync(path.dirname(target), { recursive: true })
  writeFileSync(target, canvas.toSvg())
}

// ---------- Bekem the marmot: 16 x 16, facing the viewer ----------

const MARMOT = { K: C.ink, B: C.fur, D: C.furDark, L: C.belly, W: C.white, P: C.cheek }

const HEAD_TOP = ['................', '...KK......KK...', '..KBBK....KBBK..', '..KBBBKKKKBBBK..', '.KBBBBBBBBBBBBK.']
const BODY = ['.KBBBLLLLLLBBBK.', '.KBBDLLLLLLDBBK.', '.KDBBLLLLLLBBDK.', '..KDDKKKKKKDDK..', '...KK......KK...']

/** eyes: rows 5-6, muzzle: rows 7-10. */
function marmot(eyes, muzzle) {
  return fromRows([...HEAD_TOP, ...eyes, ...muzzle, ...BODY], MARMOT)
}

const MUZZLE_TEETH = ['.KBBBBLLLLBBBBK.', '.KBBBLLKKLLBBBK.', '..KBBLLLLLLBBK..', '..KBBBLWWLBBBK..']
const MUZZLE_SMILE = ['.KBPBBLLLLBBPBK.', '.KBBBLLKKLLBBBK.', '..KBBLKLLKLBBK..', '..KBBBLKKLBBBK..']
const MUZZLE_OPEN = ['.KBBBBLLLLBBBBK.', '.KBBBLLKKLLBBBK.', '..KBBLLKKLLBBK..', '..KBBBLKKLBBBK..']

const idle = marmot(['.KBBKBBBBBBKBBK.', '.KBBKBBBBBBKBBK.'], MUZZLE_TEETH)
const relaxed = marmot(['.KBBBBBBBBBBBBK.', '.KBKKKBBBBKKKBK.'], MUZZLE_SMILE)
const alert = marmot(['.KBWWBBBBBBWWBK.', '.KBWKBBBBBBKWBK.'], MUZZLE_TEETH)
const whistling = marmot(['.KBKBBBBBBBBKBK.', '.KBBKBBBBBBKBBK.'], MUZZLE_OPEN)

/** Mood portraits: 20 x 20, the marmot at the bottom with room above for a mood mark. */
function portrait(sprite, mark) {
  const canvas = new Canvas(20, 20).draw(sprite, 2, 4)
  mark(canvas)
  return canvas
}

function note(canvas, x, y) {
  canvas.rect(x + 1, y, 2, 1, C.ink).px(x + 1, y + 1, C.ink).rect(x, y + 2, 2, 1, C.ink)
}

save('bekem/idle.svg', idle)
save(
  'bekem/relaxed.svg',
  portrait(relaxed, (c) => c.px(16, 1, C.sun).px(15, 2, C.sun).px(17, 2, C.sun).px(16, 3, C.sun).px(16, 2, C.white)),
)
save(
  'bekem/alert.svg',
  portrait(alert, (c) => c.rect(9, 0, 2, 2, C.coral).rect(9, 3, 2, 1, C.coral)),
)
save(
  'bekem/whistling.svg',
  portrait(whistling, (c) => {
    note(c, 15, 0)
    note(c, 2, 1)
  }),
)

// Sprite sheets: two 16 x 16 frames side by side.
const hop = new Canvas(16, 16)
  .draw(idle, 0, -1)
  .rect(0, 13, 16, 3, null)
  .draw(fromRows(['...KDDKKKKDDK...', '....KK....KK....'], MARMOT), 0, 13)
save('bekem/run.svg', new Canvas(32, 16).draw(idle, 0, 0).draw(hop, 16, 0))

console.log('Placeholder art written to public/bekem')
